insert into public.registry_provenance_links (original_relationship_id,source_entity_type,source_slug,source_kind,source_entity,source_record_id,source_staging_record_id,target_entity_type,target_slug,target_media_asset_id,relationship_type,relationship_role,relationship_status,metadata,original_created_at,original_updated_at) select r.id,r.source_entity_type,r.source_slug,r.source_kind,r.source_entity,r.source_record_id,r.source_staging_record_id,r.target_entity_type,r.target_slug,ma.id,r.relationship_type,r.relationship_role,r.relationship_status,r.metadata,r.created_at,r.updated_at from public.registry_entity_relationships r join public.registry_media_assets ma on ma.slug=r.target_slug where r.source_entity_type='chart_entries' and r.target_entity_type='media_assets' and r.relationship_type='entity_media' and r.relationship_role='artwork' on conflict (original_relationship_id) do nothing;;
